compile.workshop:
variables {
    global:
        0: value
        1: i
}

rule ("for continue before later breaks") {
    event {
        Ongoing - Global;
    }
    actions {
        For Global Variable(i, 0, 5, 1);
            If(True);
                Skip(Value In Array(Array(6, 0, 2, 4), Add(1, Index Of Array Value(Array(1, 2, 3), Global.value))));
            //__label_switch_3_0__:
            Modify Global Variable(value, Add, 1);
            Skip(6);
            //__label_switch_3_1__:
            Modify Global Variable(value, Add, 2);
            Else;
            //__label_switch_3_2__:
            Modify Global Variable(value, Add, 3);
            Else;
            //__label_switch_3_default__:
            End;
            Modify Global Variable(value, Add, 5);
            //__label_continue_2__:
        End;
    }
}

rule ("while continue before a later break") {
    event {
        Ongoing - Global;
    }
    actions {
        While(Compare(Global.value, <, 10));
            If(True);
                Skip(Value In Array(Array(2, 0), Add(1, Index Of Array Value(Array(1), Global.value))));
            //__label_switch_5_0__:
            Modify Global Variable(value, Add, 1);
            Skip(4);
            //__label_switch_5_default__:
            Modify Global Variable(value, Add, 2);
            Else;
            End;
            Modify Global Variable(value, Add, 5);
            //__label_continue_4__:
        End;
    }
}

rule ("conditional continue before the arm's own break") {
    event {
        Ongoing - Global;
    }
    actions {
        While(Compare(Global.value, <, 10));
            If(True);
                Skip(Value In Array(Array(4, 0, 3), Add(1, Index Of Array Value(Array(1, 2), Global.value))));
            //__label_switch_7_0__:
            Skip If(Compare(Global.value, ==, 1), 5);
            Modify Global Variable(value, Add, 1);
            Else;
            //__label_switch_7_1__:
            Modify Global Variable(value, Add, 2);
            //__label_switch_7_default__:
            End;
            Modify Global Variable(value, Add, 5);
            //__label_continue_6__:
        End;
    }
}

rule ("dead code after own break") {
    event {
        Ongoing - Global;
    }
    actions {
        For Global Variable(i, 0, 5, 1);
            If(True);
                Skip(Value In Array(Array(6, 0, 3), Add(1, Index Of Array Value(Array(1, 2), Global.value))));
            //__label_switch_10_0__:
            Skip If(Compare(Global.value, ==, 1), 8);
            Else;
            Modify Global Variable(value, Add, 7);
            //__label_switch_10_1__:
            Skip If(Compare(Global.value, ==, 2), 5);
            Modify Global Variable(value, Add, 2);
            Else;
            //__label_switch_10_default__:
            Modify Global Variable(value, Add, 3);
            End;
            Modify Global Variable(value, Add, 5);
            //__label_continue_8__:
            //__label_continue_9__:
        End;
    }
}

